WF.uiState={load:function(){try{const raw=localStorage.getItem("wf_checklist_ui_state");return raw?JSON.parse(raw):{}}catch(err){return console.error("Unreadable or corrupted localStorage UI state, reset.",err),{}}},save:function(state){try{localStorage.setItem("wf_checklist_ui_state",JSON.stringify(state))}catch(err){console.error("Failed to save UI state to localStorage.",err)}},STORAGE_KEY:"wf_checklist_ui_state"};